const carrierLogos = {
  "UPS": "data:image/svg+xml;base64,",
  "FEDEX": "data:image/svg+xml;base64,",
  "DHL": "data:image/svg+xml;base64,",
  "CHRONOPOST": "data:image/svg+xml;base64,",
  "DPD": "data:image/svg+xml;base64,"
};
const carrierLogoUrls = Object.fromEntries(Object.entries(carrierLogos).map(([carrier, data]) => {
 const svg = Uint8Array.from(atob(data.split(',')[1]), byte => byte.charCodeAt(0));
 return [carrier, URL.createObjectURL(new Blob([svg], { type: 'image/svg+xml' }))];
}));
const transportIcons = {
 '空运': ['air', 'M22 2 9 15M22 2l-7 20-4-9-9-4z'],
 '铁路': ['rail', 'M5 5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2zM5 10h14M8 14h.01M16 14h.01M8 17l-3 4m11-4 3 4'],
 '卡航': ['road', 'M2 5h13v12H2zM15 9h4l3 4v4h-7M8 17a2 2 0 1 1-4 0 2 2 0 0 1 4 0zm12 0a2 2 0 1 1-4 0 2 2 0 0 1 4 0z'],
 '船运': ['sea', 'M3 14l9-4 9 4-3 5H6zM7 12V6h10v6M12 3v7M2 22c2 0 2-1 4-1s2 1 4 1 2-1 4-1 2 1 4 1 2-1 4-1']
};
function transportBadge(mode) {
 const label = mode === '海运' ? '船运' : mode;
 const icon = Object.hasOwn(transportIcons, label) && transportIcons[label];
 if (!icon) return esc(label || '未填写');
 const [style, path] = icon;
 return `<span class="transportBadge ${style}"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${path}"/></svg>${label}</span>`;
}
function carrierTracking(shipment) {
 const key = shipment.carrier?.trim().toUpperCase();
 const logo = Object.hasOwn(carrierLogoUrls, key) ? carrierLogoUrls[key] : '';
 const image = logo ? `<img class="carrierLogo" src="${logo}" alt="" data-carrier="${key}">` : '';
 return `<span class="tracking carrierTracking"><span class="carrierBadge">${image}<span>${esc(shipment.carrier)}</span></span><span>${esc(shipment.number)}</span></span>`;
}
