async function uploadDocument(id,kind,file){if(!file||!file.size)return;if(file.size>16*1024*1024)throw Error(file.name+' 超过16MB');const base64=await new Promise((yes,no)=>{const r=new FileReader();r.onload=()=>yes(r.result.split(',')[1]);r.onerror=no;r.readAsDataURL(file);});return api('/api/shipments/'+id+'/documents',{kind,name:file.name,base64});}

