function trackingUrl(s){const n=encodeURIComponent(s.number);return s.carrier==='UPS'?`https://www.ups.com/track?loc=en_FR&tracknum=${n}`:s.carrier==='FedEx'?`https://www.fedex.com/fedextrack/?trknbr=${n}`:s.carrier==='DHL'?`https://www.dhl.com/fr-en/home/tracking.html?tracking-id=${n}`:`https://t.17track.net/en#nums=${n}`;}
function shipmentTimeline(events){
 const ordered=[...events].reverse();
 const isTransportUpdate=event=>!!event.original_time&&event.kind==='unknown';
 const updates=ordered.filter(isTransportUpdate);
 const milestones=ordered.filter(event=>!isTransportUpdate(event));
 const render=event=>`<div class="event"><strong>${event.original_time?esc(event.original_time)+'（原始时间）':fmt(event.time)}${isTransportUpdate(event)?'':'　'+esc(labels[event.kind])}</strong><p>${esc(event.description)}</p>${event.original_time?'':`<small>${[event.location,event.source&&'来源：'+event.source].filter(Boolean).map(esc).join(' · ')}</small>`}</div>`;
 const history=milestones.length?`<div class="timeline">${milestones.map(render).join('')}</div>`:'';
 const transport=updates.length?`<details class="documentSection"><summary>运输更新（${updates.length} 条）</summary><div class="timeline">${updates.map(render).join('')}</div></details>`:'';
 return history+transport||'<p class="empty">暂无轨迹。</p>';
}
function shipmentDispatchDate(shipment){
 const time=shipment.events.some(event=>event.kind==='label')?shipment.metrics.label:null;
 return time?new Date(time).toLocaleDateString('zh-CN',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}):'待确认';
}
function mobileShipmentAge(shipment){
 const start=shipment.metrics.label;
 if(!start)return '发出时间待确认';
 const end=shipment.metrics.delivered||state.now||new Date().toISOString();
 const elapsed=Math.max(0,Math.floor((Date.parse(end)-Date.parse(start))/86400000));
 return shipment.metrics.delivered?'发出 '+elapsed+' 天后签收':'已发出 '+elapsed+' 天';
}
function currentShipmentStatusClass(shipment){
 const status=currentShipmentStatus(shipment);
 return ({'已发车':'departed','已开船':'departed','已到港':'transit','已到站':'transit','已入仓':'transit','已提柜':'transit','已提取':'pickup','派送中':'out','已签收':'delivered'})[status]||shipment.metrics.status;
}
function currentShipmentStatus(shipment){
 const status=shipment.metrics.status;
 if(shipment.transport_mode==='铁路'&&!['exception','partial'].includes(status)){
  const index=railProgress(shipment).findLastIndex(([,time])=>Boolean(time));
  if(index>=0)return ['已入仓','已发车','已到站','已提取','派送中','已签收'][index];
 }
 if(shipment.transport_mode==='卡航'&&!['exception','partial'].includes(status)){
  const index=truckProgress(shipment).findLastIndex(([,time])=>Boolean(time));
  if(index>=0)return ['已发车','已到港','已提取','派送中','已签收'][index];
 }
 if(shipment.transport_mode==='海运'&&!['exception','partial'].includes(status)){
  const steps=seaProgress(shipment);
  const index=steps.findLastIndex(([,time])=>Boolean(time));
  if(index>=0)return ['已入仓','已开船','已到港','已提柜','派送中','已签收'][index];
 }
 return labels[status];
}
function railProgress(shipment){
 const find=pattern=>shipment.events.find(event=>event.original_time
  && !/预计|计划|准备|尚未|未到/.test(event.description)
  && pattern.test(event.description))?.original_time;
 return [
  ['入仓',find(/入仓成功|货物已入仓/)],
  ['发车',find(/已发车|已发运|已启运/)],
  ['到站',find(/已到站|已到达目的站|已抵达目的站/)],
  ['提取',shipment.metrics.pickup],
  ['派送',shipment.metrics.out],
  ['签收',shipment.metrics.status==='partial'?null:shipment.metrics.delivered]
 ];
}
