 '<path d="m3 9 9-6 9 6v12H3zm4 12v-9h10v9m-6-5h2"/>',
 '<rect x="6" y="3" width="12" height="15" rx="3"/><path d="M6 10h12M12 3v7M8 21l2-3m6 3-2-3"/><circle cx="9" cy="14" r="1"/><circle cx="15" cy="14" r="1"/>',
