 '<path d="M4 11h16v9H4zm0 0 3-4h10l3 4m-8 5V3m-3 3 3-3 3 3"/>',
 '<path d="m3 10 9-7 9 7M6 9v11h12V9m-8 11v-6h4v6"/>',
