function updateSelectAll(rows){
 const all=$('#selectShipments');
 const count=rows.filter(row=>checkedShipments.has(row.id)).length;
 all.disabled=!rows.length;
 all.checked=rows.length>0&&count===rows.length;
 all.indeterminate=count>0&&count<rows.length;
}
$('#rows').addEventListener('change',event=>{
 const checkbox=event.target,id=checkbox.dataset.selectShipment;
 if(!id)return;
 if(checkbox.checked)checkedShipments.add(id);
 else checkedShipments.delete(id);
 updateSelectAll(visible());
});
$('#selectShipments').onchange=event=>{
 for(const row of visible()){
  if(event.target.checked)checkedShipments.add(row.id);
  else checkedShipments.delete(row.id);
 }
 render();
};
