function prepareNewShipment(){ocrGeneration++;uploading=false;$('#saveShipment').disabled=false;$('#file').disabled=false;$('#manualTrackingFields').hidden=false;$('#recognizedTracking').hidden=true;$('#shipmentForm').reset();$('#shipmentSaveError').hidden=true;$('#salesOwner').innerHTML=ownerOptions();$('#salesOwner2').innerHTML=ownerOptions('',true);$('#newShippingFields').innerHTML=shippingInputs({},true);if(!canWrite())$('#newShippingFields .privateFields').remove();$('#newInvoice').closest('label').hidden=!canWrite();attachment=null;$('#labelPreview').hidden=true;$('#uploadHint').textContent='上传后自动识别单号；识别不到再手动填写';}
$('#newShipment').onclick=()=>{location.hash='shipment/new';};
async function recognizeNewLabel(id,generation){
 $('#ocrHint').textContent='正在自动识别单号…';$('#ocr').disabled=true;$('#manualTrackingFields').hidden=true;$('#recognizedTracking').hidden=true;$('#candidates').hidden=true;
 try{const result=await api('/api/ocr/'+id,{});if(generation!==ocrGeneration)return;const candidates=result.candidates||[];$('#ocrHint').textContent=result.message;
 if(candidates.length===1){applyCandidate(candidates[0]);}
 else if(candidates.length>1){$('#candidates').innerHTML='<option value="">请选择对应包裹的单号</option>'+candidates.map((c,i)=>'<option value="'+i+'">'+esc(c.carrier+' · '+c.number)+'</option>').join('');$('#candidates').hidden=false;$('#candidates').onchange=e=>{if(e.target.value!=='')applyCandidate(candidates[Number(e.target.value)]);};$('#manualTrackingFields').hidden=false;}
 else{$('#manualTrackingFields').hidden=false;$('#shipmentForm').elements.carrier.value='其他';$('#ocrHint').textContent=result.message+'，请物流专员填写面单单号。';}
 }catch(err){if(generation!==ocrGeneration)return;$('#manualTrackingFields').hidden=false;$('#ocrHint').textContent='自动识别未完成，请物流专员填写面单单号。';toast(err.message);}finally{if(generation===ocrGeneration)$('#ocr').disabled=false;}
}
function applyCandidate(candidate){const form=$('#shipmentForm');if(form.elements.carrier.value!==candidate.carrier)form.elements.carrier_code.value='';form.elements.number.value=candidate.number;form.elements.carrier.value=candidate.carrier;$('#recognizedText').textContent='已识别：'+candidate.carrier+' · '+candidate.number;$('#recognizedTracking').hidden=false;$('#manualTrackingFields').hidden=true;}
$('#correctNumber').onclick=()=>{$('#manualTrackingFields').hidden=false;$('#shipmentForm').elements.number.focus();};
$('#file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const generation=++ocrGeneration;attachment=null;$('#labelPreview').hidden=true;uploading=true;$('#file').disabled=true;$('#saveShipment').disabled=true;$('#shipmentForm').elements.number.value='';$('#manualTrackingFields').hidden=true;$('#recognizedTracking').hidden=true;$('#uploadHint').textContent='正在上传并识别面单…';try{const r=await api('/api/upload',{base64:await fileBase64(file,8)});if(generation!==ocrGeneration)return;attachment=r.id;$('#preview').src=r.url;$('#labelPreview').hidden=false;$('#uploadHint').textContent='面单已保存，正在自动识别单号';await recognizeNewLabel(r.id,generation);if(generation===ocrGeneration)$('#uploadHint').textContent='面单已上传';}catch(err){if(generation===ocrGeneration){$('#manualTrackingFields').hidden=false;toast(err.message);$('#uploadHint').textContent='上传或识别失败，请重新上传或手动填写';}}finally{if(generation===ocrGeneration){uploading=false;$('#saveShipment').disabled=false;$('#file').disabled=false;}}};
$('#ocr').onclick=async()=>{if(!attachment||uploading)return;const generation=ocrGeneration;uploading=true;$('#saveShipment').disabled=true;try{await recognizeNewLabel(attachment,generation);}finally{if(generation===ocrGeneration){uploading=false;$('#saveShipment').disabled=false;}}};
$('#shipmentForm').onsubmit=async e=>{e.preventDefault();if(uploading)return;const error=$('#shipmentSaveError');error.hidden=true;$('#saveShipment').disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.attachment=attachment;const s=await api('/api/shipments',data);const errors=[];for(const[kind,input]of[['invoice','#newInvoice'],['products','#newProducts']]){try{await uploadDocument(s.id,kind,$(input).files[0]);}catch(err){errors.push(err.message);}}await refresh();showDetail(s.id);toast(errors.length?'运单已保存，部分文件上传失败，可在详情重试：'+errors.join('；'):'运单与附件已保存');}catch(err){if(!$('#shipmentCreatePage').hidden){error.textContent=err.message;error.hidden=false;error.focus();}else toast(err.message);}finally{$('#saveShipment').disabled=false;}};
 $('#export').onclick=()=>{const selected=state.shipments.filter(s=>checkedShipments.has(s.id));const rows=selected.length?selected:visible();const cells=[['产品','运单号','承运商','运输方式','归属销售','批次','状态','建单时间','揽收时间','签收时间','建单到揽收天数','等待中','揽收到签收天数'],...rows.map(s=>[s.product,s.number,s.carrier,s.transport_mode,s.sales_name,s.batch,currentShipmentStatus(s),s.metrics.label,s.metrics.pickup,s.metrics.delivered,s.metrics.waitDays,s.metrics.waitOpen?'是':'否',s.metrics.transitDays])];const text='\ufeff'+cells.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='物流时效-'+new Date().toISOString().slice(0,10)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
refresh().catch(()=>{});setInterval(()=>{if(state&&$('#shipmentCreatePage').hidden)refresh().catch(()=>{});},30000);

let accountDirectory=[];
function renderAccounts(){
 const query=$('#accountSearch').value.trim().toLowerCase();
 const rows=accountDirectory.filter(user=>[user.username,user.name].some(value=>value.toLowerCase().includes(query)));
 $('#userList').innerHTML=rows.map(user=>`<tr><td>${esc(user.username)}</td><td>${esc(user.name)}</td><td>${roleNames[user.role]}</td><td>${user.active?'启用':'关闭'}</td><td><button class="link" data-toggle-account="${user.id}">${user.active?'关闭':'启用'}</button><button class="link dangerText" data-remove-account="${user.id}" ${user.id===state.user.id?'disabled':''}>删除</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">没有匹配的账户</td></tr>';
}
