function showWorkspacePage(renderDetail=true){
 const myDispatch=['SALES','SUPPORT'].includes(state?.user?.role)&&location.hash==='#my-dispatch';
 $('#myDispatchPage').hidden=!myDispatch;
 $('#navMyDispatch').classList.toggle('active',myDispatch);
 if(myDispatch)showDispatchQueue($('#myDispatchList'));
 const accountsPage=$('#accountsPage');
 const accounts=state?.user?.role==='ADMIN'&&location.hash==='#accounts';
 if(accounts&&accountsPage.hidden)showUsers();
 accountsPage.hidden=!accounts;
 $('#navUsers').classList.toggle('active',accounts);
 const companies=canWrite()&&location.hash==='#freight-companies';
 const createPage=$('#shipmentCreatePage');
 const creating=canWrite()&&location.hash==='#shipment/new';
 if(creating&&createPage.hidden){prepareNewShipment();window.scrollTo(0,0);}
 createPage.hidden=!creating;
 const id=location.hash.startsWith('#shipment/')?location.hash.slice(10):null;
 const shipment=id&&state?.shipments.some(s=>s.id===id);
 const detailPage=$('#shipmentDetailPage');
 const needsRender=shipment&&(detailPage.hidden||selected!==id);
 overviewPage.hidden=!!(companies||shipment||creating||myDispatch||accounts);
 detailPage.hidden=!shipment;
 if(renderDetail&&needsRender)showDetail(id);
 $('#companyPage').hidden=!companies;
 $('#navOverview').classList.toggle('active',!companies&&!myDispatch&&!accounts);
 $('#navCompanies').classList.toggle('active',companies);
 if(companies&&$('#companyForm').hidden)renderCompanyDirectory();
}
