let freightCompanies=[];
let editingCompanyId='';

function showCompanySuggestions(input){
 const list=input.closest('.shipmentCompanyPicker').querySelector('.companySuggestions');
 const query=input.value.trim().toLowerCase();
 const matches=freightCompanies.filter(company=>company.name.toLowerCase().includes(query));
 list.replaceChildren(...matches.map(company=>{
  const option=document.createElement('button');
  option.type='button';
  option.textContent=company.name;
  option.onclick=()=>{input.value=company.name;input.focus();list.hidden=true;input.setAttribute('aria-expanded','false');};
  return option;
 }));
 list.hidden=!matches.length;
 input.setAttribute('aria-expanded',String(!list.hidden));
}
for(const event of ['input','focusin'])document.addEventListener(event,e=>{
 if(e.target.matches('.shipmentCompanyPicker input'))showCompanySuggestions(e.target);
});
document.addEventListener('focusout',e=>{
 const picker=e.target.closest('.shipmentCompanyPicker');
 if(!picker||picker.contains(e.relatedTarget))return;
 picker.querySelector('.companySuggestions').hidden=true;
 picker.querySelector('input').setAttribute('aria-expanded','false');
});
document.addEventListener('keydown',e=>{
 const picker=e.target.closest('.shipmentCompanyPicker');
 if(!picker)return;
 const input=picker.querySelector('input'),list=picker.querySelector('.companySuggestions');
 if(e.key==='Escape'&&!list.hidden){
  e.preventDefault();
  input.focus();
  list.hidden=true;
  input.setAttribute('aria-expanded','false');
 }
 if(e.key==='ArrowDown'&&e.target===input){
  e.preventDefault();
  if(list.hidden)showCompanySuggestions(input);
  list.querySelector('button')?.focus();
 }
});
async function refreshCompanyNames(){
 $('#navCompanies').hidden=!canWrite();
 freightCompanies=[];
 if(canWrite()){
  try{freightCompanies=(await api('/api/freight-companies')).companies;}
  catch(error){console.warn('物流公司加载失败',error);}
 }
 showWorkspacePage();
}
function showCompany(id){
 const company=freightCompanies.find(item=>item.id===id);
 const form=$('#companyForm');
 editingCompanyId=company?.id||'';
 $('#companyDirectory').hidden=true;
 $('#companyFormTitle').textContent=company?'编辑物流公司':'新增物流公司';
 form.hidden=false;
 form.reset();
 for(const [key] of companyFields)form.elements[key].value=company?.[key]||'';
 const image=$('#companyImage');
 image.hidden=!company?.has_image;
 if(company?.has_image)image.href='/api/freight-companies/'+company.id+'/bank-image';
 else image.removeAttribute('href');
 const links=$('#companyLinks');
 links.replaceChildren();
 for(const [field,label] of [['tracking_url','打开查询网站'],['website','打开公司网站']]){
  if(!company?.[field])continue;
  const link=document.createElement('a');
  link.href=company[field];
  link.textContent=label;
  link.target='_blank';
  link.rel='noopener';
  links.append(link,'　');
 }
}
function renderCompanyDirectory(){
 $('#companyForm').hidden=true;
 $('#companyDirectory').hidden=false;
 const search=$('#companySearch').value.trim().toLowerCase();
 const matches=freightCompanies.filter(company=>['name','contact','wechat','manager']
  .some(field=>String(company[field]||'').toLowerCase().includes(search)));
 $('#companyResults').innerHTML=matches.length?matches.map(company=>`
  <article class="notice companyRecord">
   <div>
    <h3>${esc(company.name)}</h3>
    <dl class="companyDetails">
     ${companyFields.slice(1).map(([key,label])=>{
      const value=company[key];
      const isLink=(key==='tracking_url'||key==='website')&&/^https?:\/\//i.test(value);
      return `<div><dt>${label}</dt><dd>${isLink
       ?`<a href="${esc(value)}" target="_blank" rel="noopener noreferrer">${esc(value)}</a>`
       :esc(value||'未填写')}</dd></div>`;
     }).join('')}
     <div><dt>结算银行图片</dt><dd>${company.has_image
      ?`<a href="/api/freight-companies/${encodeURIComponent(company.id)}/bank-image" target="_blank" rel="noopener noreferrer">查看图片</a>`
      :'未上传'}</dd></div>
    </dl>
   </div>
   <div class="companyActions">
    <button type="button" class="ghost" data-company-edit="${esc(company.id)}">编辑</button>
    <button type="button" class="danger" data-company-delete="${esc(company.id)}">删除</button>
   </div>
  </article>`).join(''):`<p class="empty">${search?'没有找到匹配的物流公司':'还没有添加物流公司'}</p>`;
}
